package shop.ultimatesmp.crates;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import java.nio.file.*;import java.io.*;
import org.bukkit.*;import org.bukkit.block.Block;import org.bukkit.command.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.*;import org.bukkit.event.inventory.*;import org.bukkit.event.player.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.java.JavaPlugin;

public final class UltimateCrates extends JavaPlugin implements Listener,TabCompleter {
 private final Map<String,Crate> crates=new TreeMap<>();private final Map<String,String> bindings=new HashMap<>();private final Map<UUID,Menu> menus=new HashMap<>();private final Set<UUID> saving=new HashSet<>();private final Set<UUID> claiming=new HashSet<>();private final Map<UUID,Long> openings=new HashMap<>();
 private final ExecutorService io=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"UltimateCrates-Store");t.setDaemon(true);return t;});private final AtomicBoolean reading=new AtomicBoolean();private CrateStore store;private volatile boolean stopping;private boolean loaded;private JavaPlugin network;private java.lang.reflect.Method networkReady;private NamespacedKey keyId,blockId;private Path links;
 private enum Kind {LIST,EDIT,WEIGHT,PREVIEW}
 private static final class Draft {final String id;String name;final long revision;final ArrayList<Crate.Reward> rewards=new ArrayList<>(Collections.nCopies(45,null));Draft(Crate c){id=c.id();name=c.name();revision=c.revision();for(int i=0;i<c.rewards().size();i++){var r=c.rewards().get(i);rewards.set(i,new Crate.Reward(r.item(),r.weight()));}}}
 private static final class Menu implements InventoryHolder {Inventory inv;final Kind kind;final String id;final Draft draft;final int page,index;Menu(Kind kind,String id,Draft draft,int page,int index){this.kind=kind;this.id=id;this.draft=draft;this.page=page;this.index=index;}public Inventory getInventory(){return inv;}}
 @Override public void onEnable(){saveDefaultConfig();keyId=new NamespacedKey(this,"key");blockId=new NamespacedKey(this,"crate");links=getDataFolder().toPath().resolve("bindings.yml");
  try{if(Files.exists(links)){var y=new YamlConfiguration();y.load(links.toFile());for(String k:y.getKeys(false)){String v=y.getString(k);if(v==null||!v.matches("[a-z0-9_-]{1,32}"))throw new IllegalArgumentException("Invalid binding");bindings.put(k,v);}}
   network=(JavaPlugin)Bukkit.getPluginManager().getPlugin("BlinkNetwork");if(network!=null&&network.isEnabled())networkReady=network.getClass().getMethod("isPlayerReady",Player.class);else network=null;
   String mode=getConfig().getString("storage","auto");if(!Set.of("auto","local").contains(mode))throw new IllegalArgumentException("storage must be auto or local");String url=null,user="",password="";
   if(mode.equals("auto")&&network!=null){url=credential("BLINK_NETWORK_JDBC_URL","database.jdbc-url").replaceFirst("^jdbc:mysql:","jdbc:mariadb:");user=credential("BLINK_NETWORK_DB_USER","database.username");password=credential("BLINK_NETWORK_DB_PASSWORD","database.password");if(!url.startsWith("jdbc:mariadb:"))throw new IllegalArgumentException("Shared crates require MySQL/MariaDB");}
   store=new CrateStore(getDataFolder().toPath().resolve("crates.yml"),url,user,password);Bukkit.getPluginManager().registerEvents(this,this);Objects.requireNonNull(getCommand("crates")).setTabCompleter(this);Bukkit.getScheduler().runTaskTimer(this,this::refresh,1,20L*Math.max(5,getConfig().getInt("refresh-seconds",10)));getLogger().info(url==null?"Local crate storage; reward editor requires ultimatecrates.admin.":"Shared network crate storage; reward editor requires ultimatecrates.admin.");
  }catch(Exception e){getLogger().severe("Crates setup failed ("+e.getClass().getSimpleName()+"). Check storage mode, database type and bindings.yml.");Bukkit.getPluginManager().disablePlugin(this);}}
 private String credential(String env,String path){String s=System.getenv(env);return s==null||s.isBlank()?network.getConfig().getString(path,""):s;}
 private void main(Runnable r){if(!stopping&&isEnabled())Bukkit.getScheduler().runTask(this,()->{if(!stopping)r.run();});}
 private void refresh(){if(stopping||!reading.compareAndSet(false,true))return;io.execute(()->{try{store.initialize();Map<String,String> values=store.load();main(()->{try{Map<String,Crate> next=new TreeMap<>();for(var entry:values.entrySet()){Crate c=decode(entry.getValue());if(!c.id().equals(entry.getKey()))throw new IllegalArgumentException("ID mismatch");next.put(c.id(),c);}crates.clear();crates.putAll(next);loaded=true;}catch(Exception e){loaded=false;getLogger().warning("Invalid stored rewards; openings paused ("+e.getClass().getSimpleName()+").");}});}catch(Exception e){main(()->loaded=false);getLogger().warning("Crate storage unavailable; openings paused ("+e.getClass().getSimpleName()+").");}finally{reading.set(false);}});}
 private String encode(Crate c){var y=new YamlConfiguration();y.set("id",c.id());y.set("name",c.name());y.set("revision",c.revision());for(int i=0;i<c.rewards().size();i++){var r=c.rewards().get(i);y.set("rewards."+i+".item",r.item());y.set("rewards."+i+".weight",r.weight());}return y.saveToString();}
 private Crate decode(String payload)throws Exception{var y=new YamlConfiguration();y.loadFromString(payload);var list=new ArrayList<Crate.Reward>();var section=y.getConfigurationSection("rewards");if(section!=null)for(String k:section.getKeys(false))list.add(new Crate.Reward(y.getItemStack("rewards."+k+".item"),y.getInt("rewards."+k+".weight")));return new Crate(y.getString("id"),y.getString("name"),y.getLong("revision"),list);}
 private void save(Player player,Crate next,long previous){if(!saving.add(player.getUniqueId())){tell(player,"A save is already pending.");return;}String payload=encode(next);io.execute(()->{try{boolean ok=store.save(next.id(),previous,payload);main(()->{saving.remove(player.getUniqueId());if(ok){crates.put(next.id(),next);tell(player,"Saved "+next.name()+". Shared backends refresh within 10 seconds.");}else{tell(player,"Another admin changed this crate. Reopen the editor; your save did not overwrite it.");refresh();}});}catch(Exception e){main(()->{saving.remove(player.getUniqueId());tell(player,"Save failed. Your previous rewards are preserved; reopen the editor to try again.");});}});}
 private boolean admin(CommandSender s){return s.hasPermission("ultimatecrates.admin")||s instanceof Player p&&(p.hasPermission("ultimateranks.rank.owner")||p.hasPermission("ultimateranks.rank.dev"));}
 private boolean ready(Player p){if(!loaded)return false;if(network==null)return true;try{return network.isEnabled()&&Boolean.TRUE.equals(networkReady.invoke(network,p));}catch(Exception e){return false;}}
 private void tell(CommandSender s,String m){s.sendMessage("§5[UltimateCrates] §f"+m);}
 private ItemStack icon(Material material,String name,String... lore){ItemStack item=new ItemStack(material);ItemMeta m=item.getItemMeta();m.setDisplayName("§r"+name);m.setLore(Arrays.stream(lore).map(s->"§7"+s).toList());item.setItemMeta(m);return item;}
 private ItemStack token(Crate c,boolean key,int amount){var item=icon(key?Material.TRIPWIRE_HOOK:Material.CHEST,"§d"+c.name()+(key?" Key":" Crate"),key?"Right-click its crate to open.":"Admin: place to register this crate.");item.setAmount(amount);var m=item.getItemMeta();m.getPersistentDataContainer().set(key?keyId:blockId,PersistentDataType.STRING,c.id());item.setItemMeta(m);return item;}
 private String tag(ItemStack item,NamespacedKey key){return item==null||!item.hasItemMeta()?null:item.getItemMeta().getPersistentDataContainer().get(key,PersistentDataType.STRING);}
 private String location(Block b){return b.getWorld().getName()+":"+b.getX()+":"+b.getY()+":"+b.getZ();}
 private void persistLinks()throws Exception{var y=new YamlConfiguration();bindings.forEach(y::set);Files.createDirectories(links.getParent());Path temp=Files.createTempFile(links.getParent(),"bindings-",".tmp");try{Files.writeString(temp,y.saveToString());try{Files.move(temp,links,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,links,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}
 private boolean editingAllowed(Player p,Block b){return !b.getWorld().getName().equals("ultimate_spawn")||p.hasPermission("edit.spawn");}
 @Override public boolean onCommand(CommandSender sender,Command cmd,String label,String[] args){try{
  if(args.length==0){if(sender instanceof Player p&&admin(p)){list(p,0);return true;}tell(sender,"Right-click a crate with its key to open. Left-click for reward previews.");return true;}
  if(!admin(sender))throw new IllegalArgumentException("You need ultimatecrates.admin.");
  String sub=args[0].toLowerCase(Locale.ROOT);if(!loaded)throw new IllegalArgumentException("Crate data is still loading.");
  if(sub.equals("create")){if(!(sender instanceof Player p)||args.length<2)throw new IllegalArgumentException("In-game: /crates create <id> [display name]");String id=args[1].toLowerCase(Locale.ROOT);if(crates.containsKey(id))throw new IllegalArgumentException("That ID already exists.");String name=args.length>2?String.join(" ",Arrays.copyOfRange(args,2,args.length)):id;Crate c=new Crate(id,name,1,List.of());save(p,c,0);tell(p,"Creating crate. Use /crates edit "+id+" after it saves.");return true;}
  if(sub.equals("give")||sub.equals("givecrate")){if(args.length<3||args.length>4)throw new IllegalArgumentException("/crates "+sub+" <online player> <crate ID> [1-64]");Player target=Bukkit.getPlayerExact(args[1]);if(target==null)throw new IllegalArgumentException("Player must be on this backend; run it on their server.");if(!ready(target))throw new IllegalArgumentException("Player inventory is still loading or transferring.");Crate c=require(args[2]);int count=args.length==4?Integer.parseInt(args[3]):1;if(count<1||count>64)throw new IllegalArgumentException("Amount must be 1-64.");ItemStack[] plan=InventoryGrant.add(target.getInventory().getStorageContents(),token(c,sub.equals("give"),count));if(plan==null)throw new IllegalArgumentException("Player needs inventory space.");target.getInventory().setStorageContents(plan);tell(sender,"Gave "+count+" "+c.name()+(sub.equals("give")?" key(s).":" crate block(s)."));return true;}
  if(sub.equals("edit")){if(!(sender instanceof Player p)||args.length!=2)throw new IllegalArgumentException("/crates edit <id>");edit(p,new Draft(require(args[1])));return true;}
  if(sub.equals("rename")){if(!(sender instanceof Player p)||args.length<3)throw new IllegalArgumentException("/crates rename <id> <display name>");Crate old=require(args[1]);save(p,new Crate(old.id(),String.join(" ",Arrays.copyOfRange(args,2,args.length)),old.revision()+1,old.rewards()),old.revision());return true;}
  if(sub.equals("set")||sub.equals("remove")){if(!(sender instanceof Player p))throw new IllegalArgumentException("Use this in-game while looking at a chest/barrel.");if(args.length!=(sub.equals("set")?2:1))throw new IllegalArgumentException("/crates set <id> or /crates remove");Block b=p.getTargetBlockExact(6);if(b==null||!Set.of(Material.CHEST,Material.TRAPPED_CHEST,Material.BARREL).contains(b.getType()))throw new IllegalArgumentException("Look at a chest or barrel within 6 blocks.");if(!ready(p)||!editingAllowed(p,b))throw new IllegalArgumentException("Data must be ready; spawn editing also requires edit.spawn.");if(b.getState() instanceof org.bukkit.block.Container container&&!container.getInventory().isEmpty())throw new IllegalArgumentException("Empty the container before registering or removing it.");String loc=location(b),previous=bindings.get(loc);if(sub.equals("set"))bindings.put(loc,require(args[1]).id());else bindings.remove(loc);try{persistLinks();}catch(Exception e){if(previous==null)bindings.remove(loc);else bindings.put(loc,previous);throw e;}tell(p,sub.equals("set")?"Crate registered here.":"Crate registration removed.");return true;}
  tell(sender,"/crates create <id> [name] | edit <id> | rename <id> <name>");tell(sender,"/crates give <player> <id> [amount] — KEYS");tell(sender,"/crates givecrate <player> <id> [amount] — PLACEABLE CRATES");tell(sender,"/crates set <id> | remove (look at container)");
 }catch(IllegalArgumentException e){tell(sender,e.getMessage()==null?"Invalid arguments.":e.getMessage());}catch(Exception e){tell(sender,"Operation failed; check server storage and try again.");getLogger().warning("Crate action failed ("+e.getClass().getSimpleName()+").");}return true;}
 private Crate require(String id){Crate c=crates.get(id.toLowerCase(Locale.ROOT));if(c==null)throw new IllegalArgumentException("Unknown crate ID.");return c;}
 private void show(Player p,Menu m,String title,int size){m.inv=Bukkit.createInventory(m,size,title);menus.put(p.getUniqueId(),m);Bukkit.getScheduler().runTask(this,()->{if(p.isOnline()&&menus.get(p.getUniqueId())==m)p.openInventory(m.inv);});}
 private void list(Player p,int page){if(!ready(p)){tell(p,"Data is still loading.");return;}var m=new Menu(Kind.LIST,null,null,Math.max(0,page),0);show(p,m,"UltimateCrates • Admin",54);var values=new ArrayList<>(crates.values());for(int i=0;i<45&&i+page*45<values.size();i++){var c=values.get(i+page*45);m.inv.setItem(i,icon(Material.CHEST,c.name(),"ID: "+c.id(),"Click to edit rewards."));}m.inv.setItem(48,icon(Material.ARROW,"Previous page"));m.inv.setItem(50,icon(Material.ARROW,"Next page"));m.inv.setItem(49,icon(Material.BOOK,"Create: /crates create <id>","Give keys: /crates give <player> <id>","Register chest: /crates set <id>"));}
 private ItemStack rewardIcon(Crate.Reward reward,long total){var item=reward.item().clone();var meta=item.getItemMeta();List<String> lore=new ArrayList<>(meta.hasLore()?meta.getLore():List.of());lore.add("§dWeight: "+reward.weight()+" | "+String.format(Locale.ROOT,"%.3f%%",100.0*reward.weight()/total));lore.add("§7Left-click: weight / right-click: remove");meta.setLore(lore);item.setItemMeta(meta);return item;}
 private void edit(Player p,Draft draft){var m=new Menu(Kind.EDIT,draft.id,draft,0,0);show(p,m,"Rewards: "+draft.name,54);long total=draft.rewards.stream().filter(Objects::nonNull).mapToLong(Crate.Reward::weight).sum();for(int i=0;i<45;i++)if(draft.rewards.get(i)!=null)m.inv.setItem(i,rewardIcon(draft.rewards.get(i),total));m.inv.setItem(45,icon(Material.BOOK,"Copy items into rewards","Click an item in your inventory to copy it.","Or put an item on cursor, then click a slot.","Your original items stay with you.","Close without Save = discard changes."));m.inv.setItem(49,icon(Material.EMERALD_BLOCK,"SAVE rewards"));m.inv.setItem(53,icon(Material.BARRIER,"Cancel / discard"));}
 private void weights(Player p,Draft draft,int index){var m=new Menu(Kind.WEIGHT,draft.id,draft,0,index);show(p,m,"Reward weight",27);m.inv.setItem(13,draft.rewards.get(index).item().clone());int[] values={-100,-10,-1,1,10,100};int[] slots={9,10,11,15,16,17};for(int i=0;i<6;i++)m.inv.setItem(slots[i],icon(values[i]<0?Material.RED_CONCRETE:Material.LIME_CONCRETE,(values[i]>0?"+":"")+values[i]+" weight"));m.inv.setItem(22,icon(Material.ARROW,"Back to rewards","Current weight: "+draft.rewards.get(index).weight(),"Weights are relative; higher = more likely."));}
 private void preview(Player p,Crate c){var m=new Menu(Kind.PREVIEW,c.id(),null,0,0);show(p,m,"Preview: "+c.name(),54);long total=c.rewards().stream().mapToLong(Crate.Reward::weight).sum();for(int i=0;i<c.rewards().size();i++){var item=rewardIcon(c.rewards().get(i),total);var meta=item.getItemMeta();var lore=meta.getLore();lore.remove(lore.size()-1);meta.setLore(lore);item.setItemMeta(meta);m.inv.setItem(i,item);}m.inv.setItem(49,icon(Material.BOOK,"Preview only","Right-click the crate with a key to open."));}
 @EventHandler(priority=EventPriority.HIGHEST)public void click(InventoryClickEvent e){Menu m=menus.get(e.getWhoClicked().getUniqueId());if(m==null||e.getView().getTopInventory()!=m.inv)return;e.setCancelled(true);Player p=(Player)e.getWhoClicked();if(m.kind==Kind.PREVIEW)return;if(!admin(p)||!ready(p)){p.closeInventory();return;}int slot=e.getRawSlot();if(slot<0)return;
  if(m.kind==Kind.LIST){if(slot==48){list(p,Math.max(0,m.page-1));return;}if(slot==50){if((m.page+1)*45<crates.size())list(p,m.page+1);return;}int index=m.page*45+slot;if(slot<45&&index<crates.size())edit(p,new Draft(new ArrayList<>(crates.values()).get(index)));return;}
  if(m.kind==Kind.WEIGHT){if(slot==22){edit(p,m.draft);return;}int delta=switch(slot){case 9->-100;case 10->-10;case 11->-1;case 15->1;case 16->10;case 17->100;default->0;};if(delta!=0){var old=m.draft.rewards.get(m.index);m.draft.rewards.set(m.index,new Crate.Reward(old.item(),Math.max(1,Math.min(1000000,old.weight()+delta))));weights(p,m.draft,m.index);}return;}
  if(slot==49){List<Crate.Reward> rewards=m.draft.rewards.stream().filter(Objects::nonNull).toList();save(p,new Crate(m.id,m.draft.name,m.draft.revision+1,rewards),m.draft.revision);p.closeInventory();return;}if(slot==53){p.closeInventory();return;}
  if(slot<45){if(e.isRightClick()){m.draft.rewards.set(slot,null);edit(p,m.draft);return;}ItemStack cursor=e.getCursor();if(cursor!=null&&!cursor.getType().isAir()){copy(p,m.draft,slot,cursor);return;}if(m.draft.rewards.get(slot)!=null)weights(p,m.draft,slot);return;}
  if(slot>=m.inv.getSize()&&e.getCurrentItem()!=null&&!e.getCurrentItem().getType().isAir()){int target=m.draft.rewards.indexOf(null);if(target<0)tell(p,"All 45 reward slots are full.");else copy(p,m.draft,target,e.getCurrentItem());}
 }
 private void copy(Player p,Draft draft,int slot,ItemStack item){try{draft.rewards.set(slot,new Crate.Reward(item,1));edit(p,draft);}catch(IllegalArgumentException e){tell(p,e.getMessage());}}
 @EventHandler(priority=EventPriority.HIGHEST)public void drag(InventoryDragEvent e){Menu m=menus.get(e.getWhoClicked().getUniqueId());if(m!=null&&e.getView().getTopInventory()==m.inv)e.setCancelled(true);}
 @EventHandler public void close(InventoryCloseEvent e){Menu m=menus.get(e.getPlayer().getUniqueId());if(m!=null&&m.inv==e.getInventory())menus.remove(e.getPlayer().getUniqueId());}
 @EventHandler public void quit(PlayerQuitEvent e){menus.remove(e.getPlayer().getUniqueId());openings.remove(e.getPlayer().getUniqueId());claiming.remove(e.getPlayer().getUniqueId());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void place(BlockPlaceEvent e){String id=tag(e.getItemInHand(),blockId);if(id==null)return;String loc=location(e.getBlockPlaced());bindings.put(loc,id);try{persistLinks();tell(e.getPlayer(),"Registered "+id+" crate.");}catch(Exception ex){bindings.remove(loc);getLogger().severe("Could not persist placed crate; use /crates set "+id+" after fixing storage.");}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void placeGuard(BlockPlaceEvent e){if(tag(e.getItemInHand(),keyId)!=null){e.setCancelled(true);return;}String id=tag(e.getItemInHand(),blockId);if(id!=null&&(!admin(e.getPlayer())||!crates.containsKey(id)||!ready(e.getPlayer())||!editingAllowed(e.getPlayer(),e.getBlock())))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void breaking(BlockBreakEvent e){if(bindings.containsKey(location(e.getBlock()))){e.setCancelled(true);tell(e.getPlayer(),"Use /crates remove first. Crates cannot be broken while registered.");}}
 @EventHandler(priority=EventPriority.HIGHEST)public void use(PlayerInteractEvent e){if(e.getHand()!=EquipmentSlot.HAND||e.getClickedBlock()==null)return;String id=bindings.get(location(e.getClickedBlock()));if(id==null)return;e.setCancelled(true);Player p=e.getPlayer();if(!p.hasPermission("ultimatecrates.use")){tell(p,"You cannot use crates.");return;}if(!ready(p)){tell(p,"Crate or network data is not ready. Try shortly.");return;}Crate c=crates.get(id);if(c==null){tell(p,"This crate's rewards are unavailable.");return;}if(e.getAction()==Action.LEFT_CLICK_BLOCK){preview(p,c);return;}if(e.getAction()!=Action.RIGHT_CLICK_BLOCK)return;if(c.rewards().isEmpty()){tell(p,"This crate has no rewards yet.");return;}if(claiming.contains(p.getUniqueId()))return;long now=System.nanoTime();if(now<openings.getOrDefault(p.getUniqueId(),0L))return;openings.put(p.getUniqueId(),now+1_000_000_000L);
  ItemStack[] items=p.getInventory().getStorageContents();int key=-1;for(int i=0;i<items.length;i++)if(id.equals(tag(items[i],keyId))){key=i;break;}boolean off=false;ItemStack hand=p.getInventory().getItemInOffHand();if(key<0&&id.equals(tag(hand,keyId))){off=true;}if(key<0&&!off){tell(p,"You need a "+c.name()+" key.");return;}
  ItemStack[] source=InventoryGrant.copy(items);if(!off){source[key].setAmount(source[key].getAmount()-1);if(source[key].getAmount()==0)source[key]=null;}if(!InventoryGrant.acceptsAll(source,c.rewards().stream().map(Crate.Reward::item).toList())){tell(p,"Make room for any possible reward first. Your key was not consumed.");return;}long total=c.rewards().stream().mapToLong(Crate.Reward::weight).sum();int chosen=Crate.select(c.rewards().stream().map(Crate.Reward::weight).toList(),ThreadLocalRandom.current().nextLong(total));ItemStack reward=c.rewards().get(chosen).item().clone();ItemStack[] plan=InventoryGrant.add(source,reward);if(plan==null){tell(p,"Make inventory space first. Your key was not consumed.");return;}if(reward.hasItemMeta()&&reward.getItemMeta().getPersistentDataContainer().has(new NamespacedKey("ultimatetempgrants","voucher-id"),PersistentDataType.STRING)){
   var service=Bukkit.getPluginManager().getPlugin("UltimateTempGrants");if(service==null||!service.isEnabled()){tell(p,"Voucher rewards are unavailable. Your key was kept.");return;}
   claiming.add(p.getUniqueId());try{
    @SuppressWarnings("unchecked") CompletableFuture<ItemStack> future=(CompletableFuture<ItemStack>)service.getClass().getMethod("materializeReward",ItemStack.class).invoke(service,reward);
    future.orTimeout(10,TimeUnit.SECONDS).whenComplete((fresh,error)->main(()->{claiming.remove(p.getUniqueId());if(!p.isOnline()||!ready(p))return;if(error!=null||fresh==null){tell(p,"Voucher reward could not be prepared. Your key was kept.");return;}finishVoucher(p,c,fresh);}));
   }catch(Exception ex){claiming.remove(p.getUniqueId());tell(p,"Voucher reward could not be prepared. Your key was kept.");}return;
  }
  p.getInventory().setStorageContents(plan);if(off){hand.setAmount(hand.getAmount()-1);p.getInventory().setItemInOffHand(hand);}awardMessage(p,reward);
 }
 private void awardMessage(Player player,ItemStack reward){player.playSound(player.getLocation(),Sound.ENTITY_PLAYER_LEVELUP,.7f,1.2f);tell(player,"You received "+reward.getAmount()+" × "+reward.getType().name().toLowerCase(Locale.ROOT).replace('_',' ')+"!");}
 private void finishVoucher(Player p,Crate crate,ItemStack reward){
  ItemStack[] source=InventoryGrant.copy(p.getInventory().getStorageContents());int slot=-1;for(int i=0;i<source.length;i++)if(crate.id().equals(tag(source[i],keyId))){slot=i;break;}boolean off=slot<0;ItemStack hand=p.getInventory().getItemInOffHand();if(off&&!crate.id().equals(tag(hand,keyId))){tell(p,"Your crate key moved. No reward was claimed.");return;}
  if(!off){source[slot].setAmount(source[slot].getAmount()-1);if(source[slot].getAmount()==0)source[slot]=null;}if(!InventoryGrant.acceptsAll(source,crate.rewards().stream().map(Crate.Reward::item).toList())){tell(p,"Make inventory space. Your key was kept.");return;}ItemStack[] plan=InventoryGrant.add(source,reward);if(plan==null){tell(p,"Make inventory space. Your key was kept.");return;}p.getInventory().setStorageContents(plan);if(off){hand.setAmount(hand.getAmount()-1);p.getInventory().setItemInOffHand(hand);}awardMessage(p,reward);
 }
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void openContainer(InventoryOpenEvent e){Location l=e.getInventory().getLocation();if(l!=null&&bindings.containsKey(location(l.getBlock())))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void hopper(InventoryMoveItemEvent e){Location a=e.getSource().getLocation(),b=e.getDestination().getLocation();if(a!=null&&bindings.containsKey(location(a.getBlock()))||b!=null&&bindings.containsKey(location(b.getBlock())))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void explode(EntityExplodeEvent e){e.blockList().removeIf(b->bindings.containsKey(location(b)));}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void explode(BlockExplodeEvent e){e.blockList().removeIf(b->bindings.containsKey(location(b)));}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void piston(BlockPistonExtendEvent e){if(e.getBlocks().stream().anyMatch(b->bindings.containsKey(location(b))))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void piston(BlockPistonRetractEvent e){if(e.getBlocks().stream().anyMatch(b->bindings.containsKey(location(b))))e.setCancelled(true);}
 @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] args){if(!admin(s))return List.of();List<String> values;if(args.length==1)values=List.of("create","edit","rename","give","givecrate","set","remove");else if(args.length==2&&Set.of("edit","rename","set").contains(args[0]))values=new ArrayList<>(crates.keySet());else if(args.length==3&&Set.of("give","givecrate").contains(args[0]))values=new ArrayList<>(crates.keySet());else if(args.length==2&&Set.of("give","givecrate").contains(args[0]))values=Bukkit.getOnlinePlayers().stream().map(Player::getName).toList();else return List.of();String term=args[args.length-1].toLowerCase(Locale.ROOT);return values.stream().filter(v->v.toLowerCase(Locale.ROOT).startsWith(term)).toList();}
 @Override public void onDisable(){stopping=true;Bukkit.getScheduler().cancelTasks(this);for(Player p:Bukkit.getOnlinePlayers())if(menus.containsKey(p.getUniqueId()))p.closeInventory();menus.clear();io.shutdown();try{io.awaitTermination(6,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}io.shutdownNow();}
}
